transforms.code:
	countInfo = value['countInfo']
	displayInfo = value['display']

	instances = []
	for item in countInfo:
		rowColor = '--kcRed-60' if item['counterName'] == 'waste' else ''

		itemAsset = {"value": item['assetName'], "style": {"color": rowColor, 'textAlign': 'center'}}

		itemName = {"style": {"color": rowColor}}
		if item['workOrderName'] and displayInfo['showOrder']: itemName['value'] = "%s | %s"%(item['workOrderName'], item['itemName'] or '')
		else: itemName['value'] = "%s"%(item['itemName'] or '')

		if item['itemStatePath']:
#			stateClass = '' if item['itemStateClassName'] == item['assetName'] else item['itemStateClassName'].split("\\")[-1]
			itemStateName = "%s %s"%(item['counterName'].title(), item['itemStateName'])
#			if item['counterName'] != 'waste':	itemStateName = "%s %s %s"%(item['counterName'].title(), stateClass, item['itemStateName'])
#			else: itemStateName = "%s %s Failed"%(item['counterName'].title(), stateClass)		
		else: itemStateName = item['counterName'].title()

		itemState = {"value": itemStateName, "style": {"color": rowColor}}

		units = 'units' if item['value'] != 1 else 'unit '
		if item.has_key('earnedLaborSecs'):
			earnedLaborValue = system.kanoa.utilities.secondsToText(item['earnedLaborSecs'], {'showDays': False, 'showSecs': False, 'showDays': False}) if item['earnedLaborSecs'] > 0 else ''
		else:
			earnedLaborValue = ''
		itemValue = "{:,.0f} {}".format(item['value'], units)

		itemValue = {"value": itemValue, "style": {"color": rowColor, 'textAlign': 'center'}}
		earnedLaborValue = {"value": earnedLaborValue, "style": {"color": rowColor, 'textAlign': 'right'}}
		instances.append({"assetId": item['assetId'], "assetPath": item['assetPath'], "assetName": itemAsset, "itemName": itemName, "itemState": itemState, "itemValue": itemValue, "earnedLaborValue": earnedLaborValue})

	return instances
